class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        """
        dp maps (alternating_sum, next_parity) -> maximum product (<= limit)
        of a non‑empty subsequence where next_parity is 0 if the next
        element will be added (sign +) and 1 if it will be subtracted (sign -).
        """
        dp = {}
        for x in nums:
            # keep all states obtained by skipping x
            new_dp = dict(dp)

            # extend existing subsequences with x
            for (s, p), prod in dp.items():
                sign = 1 if p == 0 else -1          # + for even length, - for odd length
                new_s = s + sign * x
                new_p = 1 - p                       # flip parity
                new_prod = prod * x
                if new_prod <= limit:
                    if (new_s, new_p) not in new_dp or new_prod > new_dp[(new_s, new_p)]:
                        new_dp[(new_s, new_p)] = new_prod

            # start a new subsequence consisting of x alone
            new_s_start = x
            new_p_start = 1                       # after one element the next sign is -
            new_prod_start = x
            if new_prod_start <= limit:
                if (new_s_start, new_p_start) not in new_dp or new_prod_start > new_dp[(new_s_start, new_p_start)]:
                    new_dp[(new_s_start, new_p_start)] = new_prod_start

            dp = new_dp

        # best product whose alternating sum equals k
        best = -1
        for (s, _), prod in dp.items():
            if s == k and prod > best:
                best = prod
        return best

