from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    graph = [[] for _ in range(n + 1)]

    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        z = int(next(it))
        graph[x].append((y, z))
        graph[y].append((x, z))

    base = [None] * (n + 1)
    ans = [0] * (n + 1)

    for i in range(1, n + 1):
        if base[i] is None:
            q = deque()
            base[i] = 0
            q.append(i)
            comp_nodes = [i]

            while q:
                u = q.popleft()
                for (v, z) in graph[u]:
                    if base[v] is None:
                        base[v] = base[u] ^ z
                        q.append(v)
                        comp_nodes.append(v)
                    else:
                        if base[v] != (base[u] ^ z):
                            print(-1)
                            return

            vals = [base[u] for u in comp_nodes]
            m_size = len(comp_nodes)
            t_component = 0

            for bit in range(61):
                count = 0
                for val in vals:
                    if (val >> bit) & 1:
                        count += 1
                if count > m_size / 2:
                    t_component |= (1 << bit)

            for u in comp_nodes:
                ans[u] = t_component ^ base[u]

    print(" ".join(str(ans[i]) for i in range(1, n + 1)))

