from collections import defaultdict

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diag = defaultdict(list)

        # Collect elements of each diagonal (i - j constant)
        for i in range(n):
            for j in range(n):
                diag[i - j].append(grid[i][j])

        # Sort each diagonal according to the required order
        iters = {}
        for d, vals in diag.items():
            if d >= 0:          # bottom‑left triangle (including middle diagonal) -> non‑increasing
                vals.sort(reverse=True)
            else:               # top‑right triangle -> non‑decreasing
                vals.sort()
            iters[d] = iter(vals)

        # Re‑assign sorted values back to the grid
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                diff = i - j
                res[i][j] = next(iters[diff])
        return res

from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # 1. group all cells by their i - j difference
        diff_cells = {}
        for i in range(n):
            for j in range(n):
                d = i - j
                diff_cells.setdefault(d, []).append((i, j))

        # 2. process each diagonal
        for d, cells in diff_cells.items():
            # order cells from top to bottom along the diagonal
            cells.sort(key=lambda pos: pos[0])

            # extract current values
            values = [grid[i][j] for i, j in cells]

            # sort according to the required rule
            if d >= 0:                     # bottom‑left triangle (incl. main diagonal)
                values.sort(reverse=True)   # non‑increasing
            else:                          # top‑right triangle
                values.sort()               # non‑decreasing

            # write sorted values back
            for (i, j), v in zip(cells, values):
                grid[i][j] = v

        return grid

